declare(strict_types=1);

namespace Alaress\Redis\Cache;

/**
 * Standard key generator for Redis.
 *
 * Keys generated by this class will look like: `part1:part2:...:key`
 */
class KeyGenerator implements IKeyGenerator
{
    /**
     * Standard separator for key parts.
     */
    private const PART_SEPARATOR = '.';

    /**
     * @var array<string>
     */
    private array $parts;

    /**
     * Constructor
     *
     * @param string ...$parts
     */
    public function __construct(string ...$parts)
    {
        $this->parts = $parts;
    }

    /**
     * @inheritdoc
     */
    public function generateKey(string $key): string
    {
        return implode(self::PART_SEPARATOR, array_merge($this->parts, [$key]));
    }
}
